arguments.rule_content:
{
  "title": "Multiple Credential Rotation Execution Detected",
  "id": "example-sigma-credential-rotation",
  "status": "experimental",
  "description": "Detects execution of Ansible playbooks that rotate credentials across a large number of production hosts within a short time window, indicative of emergency response or malicious activity.",
  "author": "SOC Team",
  "logsource": {
    "product": "ansible",
    "service": "automation"
  },
  "detection": {
    "selection": {
      "event.type": "playbook_start",
      "playbook": "emergency_credential_rotate.yml"
    },
    "timeframe": {
      "window": "5m",
      "count": ">=200"
    },
    "condition": "selection"
  },
  "level": "high"
}
